sys_script_fix.script:
var prop = new GlideRecord('sys_properties');
if(prop.get('name','sn_grc.enable_user_hierarchy_access_control')){
	var module = new GlideRecord("sys_app_module");
	if(module.get('f231967f77d80110e723b23dbd5a99ed')) {
		module.setValue("active",prop.value);
		module.update();
	}
}
